i missed that point then. you need some small adjustments then.
add this somewhere inside the skill notetag:
Code:
user.transformTarget = target;
and you want to change the 5 lines that begin with const inside the add state tag to this so that it just uses the target's images instead of a file name
Code:
const charName = user.transformTarget._characterName;
const charIndex = user.transformTarget._characterIndex;
const faceName = user.transformTarget._faceName;
const faceIndex = user.transformTarget._faceIndex;
const battlerName = user.transformTarget._battlerName;

The game now crashes on launch with these changes. i determinded the issue lies within the state notetag so i'll add it here
<JS On Add State>
if (user.isActor()) {
user._prevCharName ??= user._characterName;
user._prevCharIndex ??= user._characterIndex;
user._prevFaceName ??= user._faceName;
user._prevFaceIndex ??= user._faceIndex;
user._prevBattlerName ??= user._battlerName;
const charName = user.transformTarget._characterName;
const charIndex = user.transformTarget._characterIndex;
const faceName = user.transformTarget._faceName;
const faceIndex = user.transformTarget._faceIndex;
const battlerName = user.transformTarget._battlerName;
user.setCharacterImage(charName, charIndex);
user.setFaceImage(faceName, faceIndex);
user.setBattlerImage(battlerName);
user.refresh();
}
</JS On Add State>
<JS On Erase State>
const charName = user._prevCharName;
const charIndex = user._prevCharIndex;
const faceName = user._prevFaceName;
const faceIndex = user._prevFaceIndex;
const battlerName = user._prevBattlerName;
user.setCharacterImage(charName, charIndex);
user.setFaceImage(faceName, faceIndex);
user.setBattlerImage(battlerName);
delete user._prevCharacterName;
delete user._prevCharacterIndex;
delete user._prevFaceName;
delete user._prevFaceIndex;
delete user._prevBattlerName;
user.refresh();
</JS On Erase State>
<JS On Erase State>
user.changeClass(user.origClass, true);
delete user.origClass;
</JS On Erase State>

